create table xxcus.xxfnd_schema_releases (
    release_code varchar2(30 byte) not null enable,
    description  varchar2(400 byte) not null enable,
    applied_date timestamp(6) default systimestamp not null enable,
    applied_by   varchar2(255 byte) not null enable
);

alter table xxcus.xxfnd_schema_releases
    add constraint xxfnd_schema_releases_pk primary key ( release_code )
        using index enable;


